import { useState, useEffect, useRef, useCallback } from 'react';

const GROQ_URL   = 'https://api.groq.com/openai/v1/chat/completions';
const GROQ_KEY   = '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';
const GROQ_MODEL = 'llama-3.3-70b-versatile';
const API        = 'http://localhost:5000/api';
const getToken   = () => localStorage.getItem('examai_token');

async function groqChat(sys, usr, max = 1000, temp = 0.7) {
  const r = await fetch(GROQ_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${GROQ_KEY}` },
    body: JSON.stringify({ model: GROQ_MODEL, max_tokens: max, temperature: temp,
      messages: [{ role: 'system', content: sys }, { role: 'user', content: usr }] }),
  });
  const d = await r.json();
  if (!r.ok) throw new Error(d?.error?.message || `AI error ${r.status}`);
  return d.choices?.[0]?.message?.content?.trim() || '';
}

function useDualSpeech(onFinal, onInterim) {
  const recs = useRef({}); const active = useRef({});
  const startChannel = useCallback((ch) => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR || active.current[ch]) return;
    const rec = new SR(); rec.continuous=true; rec.interimResults=true; rec.lang='en-US';
    rec.onresult = (e) => {
      let interim='', final='';
      for (let i=e.resultIndex;i<e.results.length;i++) {
        if (e.results[i].isFinal) final += e.results[i][0].transcript+' ';
        else interim += e.results[i][0].transcript;
      }
      if (interim) onInterim?.(ch,interim);
      if (final.trim()) onFinal(ch,final.trim());
    };
    rec.onend = () => { if (active.current[ch]) { try { rec.start(); } catch{} } };
    rec.onerror = () => { active.current[ch]=false; };
    rec.start(); recs.current[ch]=rec; active.current[ch]=true;
  },[onFinal,onInterim]);
  const stopChannel = useCallback((ch)=>{ active.current[ch]=false; try{recs.current[ch]?.stop();}catch{} delete recs.current[ch]; },[]);
  const stopAll = useCallback(()=>{ ['student','examiner'].forEach(c=>{ active.current[c]=false; try{recs.current[c]?.stop();}catch{}; }); recs.current={}; active.current={}; },[]);
  return {startChannel,stopChannel,stopAll};
}

export default function VivaRoom({ store }) {
  const [phase, setPhase] = useState('setup');
  const [form,        setForm]       = useState({ title:'', topic:'' });
  const [savedViva,   setSavedViva]  = useState(null);
  const savedVivaRef  = useRef(null);
  const [pastSessions,setPast]       = useState([]);
  const [showInvite,  setShowInvite] = useState(false);
  const [inviteMode,  setInviteMode] = useState('email');
  const [emailList,   setEmailList]  = useState('');
  const [accountSearch,setAccSearch] = useState('');
  const [allAccounts, setAllAccounts]= useState([]);
  const [foundAccounts,setFoundAccts]= useState([]);
  const [searchingAcc,setSearchingAcc]=useState(false);
  const [accountsLoaded,setAccLoaded]= useState(false);
  const [selectedAccounts,setSelAccts]=useState([]);
  const [inviting,    setInviting]   = useState(false);
  const [inviteMsg,   setInviteMsg]  = useState('');
  const [questions,   setQuestions]  = useState([]);
  const [generating,  setGenerating] = useState(false);
  const [genTopic,    setGenTopic]   = useState('');
  const [genCount,    setGenCount]   = useState(5);
  const [currentQ,    setCurrentQ]   = useState(null);
  const [transcript,  setTranscript] = useState([]);
  const [studentLive, setStudentLive]= useState('');
  const [studentInt,  setStudentInt] = useState('');
  const [examinerLive,setExamLive]   = useState('');
  const [studentRec,  setStudentRec] = useState(false);
  const [examinerRec, setExaminerRec]= useState(false);
  const [examNotes,   setExamNotes]  = useState('');
  const [verdicting,  setVerdicting] = useState(false);
  const [liveVerdict, setLiveVerdict]= useState(null);
  const AWAY_LIMIT_S = 600;
  const [adminAway,   setAdminAway]  = useState(false);
  const [awaySecondsLeft,setAwayLeft]= useState(null);
  const awayTimerRef = useRef(null);
  const mediaRecRef  = useRef(null);
  const videoChunks  = useRef([]);
  const [recording,  setRecording]  = useState(false);
  const [videoBlob,  setVideoBlob]  = useState(null);
  const adminVid = useRef(null);
  const streamRef= useRef(null);
  const [camOn, setCamOn] = useState(false);
  const [micOn, setMicOn] = useState(false);
  const [grading,  setGrading]  = useState(false);
  const [result,   setResult]   = useState(null);
  const [fullTxt,  setFullTxt]  = useState('');

  useEffect(() => {
    fetch(`${API}/viva`, { headers:{ Authorization:`Bearer ${getToken()}` } })
      .then(r=>r.ok?r.json():[]).then(d=>setPast(Array.isArray(d)?d:[])).catch(()=>{});
    const savedState = JSON.parse(localStorage.getItem('viva_active_session')||'null');
    if (savedState?.away_since) {
      const elapsed = Math.floor((Date.now()-savedState.away_since)/1000);
      if (elapsed < AWAY_LIMIT_S) {
        setForm({ title:savedState.title, topic:savedState.topic });
        setSavedViva({ viva_id:savedState.viva_id });
        savedVivaRef.current = { viva_id:savedState.viva_id };
        setQuestions(savedState.questions||[]);
        setTranscript(savedState.transcript||[]);
        setGenTopic(savedState.topic||'');
        setAdminAway(true);
        setAwayLeft(AWAY_LIMIT_S-elapsed);
      } else { localStorage.removeItem('viva_active_session'); }
    }
    return () => { clearInterval(awayTimerRef.current); };
  }, []);

  useEffect(() => {
    if (awaySecondsLeft===null) return;
    if (awaySecondsLeft<=0) { localStorage.removeItem('viva_active_session'); setAdminAway(false); setAwayLeft(null); return; }
    awayTimerRef.current = setTimeout(()=>setAwayLeft(s=>s-1),1000);
    return ()=>clearTimeout(awayTimerRef.current);
  }, [awaySecondsLeft]);

  const onFinal   = useCallback((ch,txt)=>{ if(ch==='student'){setStudentLive(p=>p+' '+txt);setStudentInt('');}else setExamLive(p=>p+' '+txt); },[]);
  const onInterim = useCallback((ch,txt)=>{ if(ch==='student') setStudentInt(txt); },[]);
  const speech    = useDualSpeech(onFinal, onInterim);

  const startMedia = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ video:true, audio:true });
      streamRef.current = s;
      setCamOn(true); setMicOn(true);
      try {
        const mr = new MediaRecorder(s,{mimeType:'video/webm;codecs=vp9,opus'});
        videoChunks.current=[];
        mr.ondataavailable=e=>{ if(e.data.size>0) videoChunks.current.push(e.data); };
        mr.onstop=()=>setVideoBlob(new Blob(videoChunks.current,{type:'video/webm'}));
        mr.start(1000); mediaRecRef.current=mr; setRecording(true);
      } catch {}
      let attempts=0;
      const attach=()=>{ if(adminVid.current) adminVid.current.srcObject=s; else if(attempts++<20) setTimeout(attach,200); };
      setTimeout(attach,300);
    } catch(e) {
      store.addToast(e.name==='NotAllowedError'?'Camera/mic access denied':'Camera error: '+e.message,'error');
    }
  };

  const stopMedia = () => {
    speech.stopAll();
    try { if(mediaRecRef.current?.state!=='inactive') mediaRecRef.current?.stop(); } catch {}
    streamRef.current?.getTracks().forEach(t=>t.stop());
    streamRef.current=null; setCamOn(false); setMicOn(false); setRecording(false);
  };

  const toggleCam = () => { streamRef.current?.getVideoTracks().forEach(t=>{t.enabled=!camOn;}); setCamOn(v=>!v); };
  const toggleExaminer = () => {
    if (!examinerRec) { speech.startChannel('examiner'); setExaminerRec(true); }
    else { speech.stopChannel('examiner'); setExaminerRec(false); }
  };

  const loadAllAccounts = async () => {
    if (accountsLoaded) return;
    setSearchingAcc(true);
    try {
      const r = await fetch(`${API}/students`,{ headers:{ Authorization:`Bearer ${getToken()}` } });
      const d = await r.json();
      const arr = Array.isArray(d)?d:[];
      setAllAccounts(arr); setFoundAccts(arr); setAccLoaded(true);
    } catch { setAllAccounts([]); setFoundAccts([]); }
    setSearchingAcc(false);
  };

  const searchAccounts = (query) => {
    const q = (query??accountSearch).trim().toLowerCase();
    if (!q) { setFoundAccts(allAccounts); return; }
    setFoundAccts(allAccounts.filter(a=>a.name?.toLowerCase().includes(q)||a.email?.toLowerCase().includes(q)));
  };

  const toggleSelectAccount = (acc) => {
    setSelAccts(prev=>prev.find(a=>a.user_id===acc.user_id)?prev.filter(a=>a.user_id!==acc.user_id):[...prev,acc]);
  };

  const sendInvites = async () => {
    const vivaId = savedVivaRef.current?.viva_id || savedViva?.viva_id;
    if (!vivaId) { store.addToast('Room ID not available — restart the viva room','error'); return; }
    const emails = inviteMode==='account'
      ? selectedAccounts.map(a=>a.email).filter(Boolean)
      : emailList.split(',').map(e=>e.trim()).filter(Boolean);
    if (!emails.length) { store.addToast('Select at least one student to invite','error'); return; }
    setInviting(true); setInviteMsg('');
    try {
      const r = await fetch(`${API}/viva/invite`,{
        method:'POST', headers:{ Authorization:`Bearer ${getToken()}`, 'Content-Type':'application/json' },
        body:JSON.stringify({ emails, title:form.title, topic:form.topic, vivaId }),
      });
      const d = r.ok?await r.json():{};
      const notifOk=d.notif_sent||0, emailOk=d.email_sent||0;
      if (notifOk>0||emailOk>0) {
        let msg=`✓ Invite sent to ${notifOk+emailOk} student(s). Room ID: ${vivaId}`;
        setInviteMsg(msg); store.addToast(`Invite sent to ${notifOk+emailOk} student(s)!`,'success');
      } else {
        setInviteMsg(`⚠ Could not notify. Share Room ID manually: ${vivaId}`);
        store.addToast('Share Room ID manually','warning');
      }
    } catch { setInviteMsg(`⚠ Network error. Room ID: ${vivaId}`); }
    if (inviteMode==='account') setSelAccts([]);
    setInviting(false);
  };

  const startRoom = async () => {
    if (!form.title.trim()) { store.addToast('Enter viva title','error'); return; }
    try {
      const sr = await fetch(`${API}/viva`,{
        method:'POST', headers:{ Authorization:`Bearer ${getToken()}`, 'Content-Type':'application/json' },
        body:JSON.stringify({ title:form.title, topic:form.topic, questions:[] }),
      });
      const sd = sr.ok?await sr.json():{};
      if (sd.viva_id) { setSavedViva(sd); savedVivaRef.current=sd; }
    } catch(e) { store.addToast('Could not create session — check backend','error'); }
    setGenTopic(form.topic);
    setPhase('room');
    setTimeout(()=>startMedia(),300);
  };

  const generateQuestions = async () => {
    const topic = genTopic.trim();
    if (!topic) { store.addToast('Enter a topic first','error'); return; }
    setGenerating(true);
    const usedQs = questions.map(q=>q.text);
    const excludeStr = usedQs.length?`\nDo NOT repeat:\n${usedQs.slice(-8).join(' | ')}`:'';
    try {
      const sys='You are an expert oral examiner. Return ONLY valid JSON array.';
      const usr=`Generate ${genCount} unique viva voce questions on "${topic}".${excludeStr}
Each with model answer for examiner.
Return: [{"question":"?","model_answer":"2-4 sentence answer"}]`;
      const raw = await groqChat(sys,usr,900,0.85);
      const arr = JSON.parse(raw.replace(/```json|```/g,'').trim());
      const newQs = arr.map((item,i)=>({ id:Date.now()+i, text:String(item.question||item), modelAnswer:String(item.model_answer||''), used:false, topic }));
      setQuestions(prev=>[...prev,...newQs]);
      setCurrentQ(prev=>prev||newQs[0]);
      store.addToast(`✓ ${newQs.length} questions ready!`,'success');
    } catch { store.addToast('Generation failed. Retry.','error'); }
    setGenerating(false);
  };

  const toggleStudent = () => {
    if (!studentRec) { speech.startChannel('student'); setStudentRec(true); store.addToast('🎙 Recording student...','info'); }
    else { speech.stopChannel('student'); setStudentRec(false); }
  };

  const checkAnswer = async () => {
    const answer=(studentLive+' '+examNotes).trim();
    if (!currentQ||!answer) { store.addToast('Record student answer first','error'); return; }
    setVerdicting(true); setLiveVerdict(null);
    try {
      const sys='You are a strict examiner. Return ONLY valid JSON.';
      const usr=`Question: ${currentQ.text}\nModel Answer: ${currentQ.modelAnswer}\nStudent Answer: ${answer}
Return: {"correct":<bool>,"score_pct":<0-100>,"verdict":"<Correct|Partially Correct|Incorrect>","feedback":"<1-2 sentences>","missing":"<key point or None>"}`;
      const raw=await groqChat(sys,usr,300,0.3);
      setLiveVerdict(JSON.parse(raw.replace(/```json|```/g,'').trim()));
    } catch { store.addToast('Verdict check failed','error'); }
    setVerdicting(false);
  };

  const saveAnswer = () => {
    const answer=(studentLive+' '+examNotes).trim();
    if (!currentQ||!answer) { store.addToast('No answer recorded','error'); return; }
    const entry={ q:currentQ.text, modelAnswer:currentQ.modelAnswer, studentAnswer:answer, examinerNotes:examinerLive.trim(), verdict:liveVerdict?.verdict||'Pending', scorePct:liveVerdict?.score_pct??null, correct:liveVerdict?.correct??null, feedback:liveVerdict?.feedback||'', ts:new Date().toISOString(), topicLabel:currentQ.topic };
    setTranscript(prev=>[...prev,entry]);
    setQuestions(prev=>prev.map(q=>q.id===currentQ.id?{...q,used:true}:q));
    setStudentLive(''); setStudentInt(''); setExamNotes(''); setLiveVerdict(null);
    speech.stopChannel('student'); setStudentRec(false);
    setCurrentQ(questions.find(q=>!q.used&&q.id!==currentQ.id)||null);
    store.addToast('✓ Saved','success');
  };

  const handleAdminLeave = () => {
    if (phase!=='room') return;
    const state={ viva_id:savedViva?.viva_id, title:form.title, topic:form.topic, questions, transcript, away_since:Date.now() };
    localStorage.setItem('viva_active_session',JSON.stringify(state));
  };

  const handleAdminReturn = () => {
    setAdminAway(false); setAwayLeft(null);
    localStorage.removeItem('viva_active_session');
    setPhase('room');
    startMedia();
    store.addToast('Resumed viva session!','success');
  };

  const endAndGrade = async () => {
    if (!transcript.length) { store.addToast('No answers saved yet','error'); return; }
    if (!window.confirm(`End viva and grade ${transcript.length} answer(s)?`)) return;
    stopMedia(); localStorage.removeItem('viva_active_session');
    setPhase('results'); setGrading(true);
    const fullText=transcript.map((e,i)=>[`---- Q${i+1} ----`,`QUESTION: ${e.q}`,`MODEL ANSWER: ${e.modelAnswer}`,`STUDENT ANSWER: ${e.studentAnswer}`,e.examinerNotes?`EXAMINER NOTES: ${e.examinerNotes}`:'',e.verdict!=='Pending'?`VERDICT: ${e.verdict} (${e.scorePct}%)`:'',`TIME: ${new Date(e.ts).toLocaleTimeString()}`].filter(Boolean).join('\n')).join('\n\n');
    setFullTxt(fullText+(examinerLive.trim()?`\n\nEXAMINER SPEECH:\n${examinerLive}`:''));
    const n=transcript.length;
    try {
      const sys='You are a strict academic examiner. Return ONLY valid JSON. Score out of 100.';
      const usr=`Topic: ${form.topic||genTopic}\n${n} questions answered.\n\nTRANSCRIPT:\n${fullText}\n\nReturn:\n{"total_score":<0-100>,"grade":"<A+|A|B|C|D|F>","correct_count":<n>,"incorrect_count":<n>,"overall_feedback":"<3-4 sentences>","strengths":["s1","s2"],"improvements":["a1","a2"],"answers":[{"question":"?","model_answer_summary":"1 sentence","student_said":"summary","score":<0-${Math.round(100/n)}>,"max_score":${Math.round(100/n)},"correct":<bool>,"verdict":"<Correct|Partially Correct|Incorrect>","feedback":"specific"}]}`;
      const raw=await groqChat(sys,usr,2000,0.2);
      const parsed=JSON.parse(raw.replace(/```json|```/g,'').trim());
      setResult(parsed);
      if (savedViva?.viva_id) {
        await fetch(`${API}/viva/${savedViva.viva_id}/result`,{
          method:'POST', headers:{ Authorization:`Bearer ${getToken()}`, 'Content-Type':'application/json' },
          body:JSON.stringify({ transcript, result:parsed, full_transcript:fullText }),
        }).catch(()=>{});
      }
    } catch(e) { store.addToast('Grading failed: '+e.message,'error'); }
    setGrading(false);
  };

  const resetAll = () => { setPhase('setup'); setResult(null); setTranscript([]); setQuestions([]); setCurrentQ(null); setStudentLive(''); setExamLive(''); setAdminAway(false); setAwayLeft(null); setShowInvite(false); setInviteMsg(''); setSelAccts([]); setEmailList(''); };

  const gc   = g => g==='A+'||g==='A'?'#16a34a':g==='F'?'#dc2626':g==='B'?'#2563eb':g==='C'?'#d97706':'#6b7280';
  const gcBg = g => g==='A+'||g==='A'?'#dcfce7':g==='F'?'#fee2e2':g==='B'?'#dbeafe':g==='C'?'#fef3c7':'#f3f4f6';
  const unusedQs = questions.filter(q=>!q.used);

  // -- Shared Invite Panel -------------------------------------
  const InvitePanel = ({ inRoom = false }) => (
    <div style={{ background:inRoom?'#1a1a2e':'#fff', border:`1px solid ${inRoom?'rgba(109,40,217,.3)':'#e8e8f0'}`, borderRadius:12, padding:18 }}>
      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:14 }}>
        <div style={{ fontSize:13, fontWeight:700, color:inRoom?'#a78bfa':'#0f0f1a', fontFamily:'Space Grotesk,sans-serif' }}>
          ✉ Invite Students
        </div>
        {(savedVivaRef.current?.viva_id || savedViva?.viva_id) && (() => {
          const rid = savedVivaRef.current?.viva_id || savedViva?.viva_id;
          return (
            <div style={{ display:'flex', alignItems:'center', gap:6, background:inRoom?'rgba(109,40,217,.15)':'#ede9fe', border:`1px solid ${inRoom?'rgba(109,40,217,.3)':'#ddd6fe'}`, borderRadius:7, padding:'3px 10px', cursor:'pointer' }}
              onClick={()=>{ navigator.clipboard.writeText(rid); store.addToast('Room ID copied!','success'); }}
              title="Click to copy Room ID">
              <span style={{ fontSize:9, color:inRoom?'#a78bfa':'#7c3aed', fontFamily:'JetBrains Mono,monospace', fontWeight:700, letterSpacing:.5 }}>ROOM ID</span>
              <span style={{ fontSize:10, color:inRoom?'#c4b5fd':'#6d28d9', fontFamily:'JetBrains Mono,monospace', fontWeight:700 }}>{rid.slice(0,14)}...</span>
              <span style={{ fontSize:9, color:inRoom?'rgba(255,255,255,.3)':'#9ca3af' }}>📋</span>
            </div>
          );
        })()}
      </div>
      <div style={{ display:'flex', gap:4, background:inRoom?'rgba(255,255,255,.05)':'#f3f4f6', padding:3, borderRadius:8, marginBottom:12 }}>
        {[{k:'email',l:'📧 By Email'},{k:'account',l:'👤 By Account'}].map(t=>(
          <button key={t.k} onClick={()=>{ setInviteMode(t.k); setInviteMsg(''); if(t.k==='account'&&!accountsLoaded) loadAllAccounts(); }}
            style={{ flex:1, padding:'6px 10px', borderRadius:6, border:'none', cursor:'pointer', fontSize:12, fontWeight:600,
              background:inviteMode===t.k?inRoom?'rgba(109,40,217,.3)':'#fff':'transparent',
              color:inviteMode===t.k?inRoom?'#c4b5fd':'#0f0f1a':inRoom?'rgba(255,255,255,.4)':'#6b7280',
              boxShadow:inviteMode===t.k?'0 1px 3px rgba(0,0,0,.1)':'' }}>
            {t.l}
          </button>
        ))}
      </div>
      {inviteMode==='email' && (
        <>
          <label style={{ display:'block', fontSize:9, fontWeight:700, color:inRoom?'#a78bfa':'#7c3aed', marginBottom:5, textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace' }}>STUDENT EMAILS</label>
          <textarea value={emailList} onChange={e=>setEmailList(e.target.value)}
            placeholder="student1@gmail.com, student2@gmail.com"
            style={{ width:'100%', background:inRoom?'rgba(255,255,255,.06)':'#f8f8fc', border:`1px solid ${inRoom?'rgba(255,255,255,.1)':'#e5e7eb'}`, borderRadius:7, padding:'8px 11px', color:inRoom?'rgba(255,255,255,.8)':'#374151', fontSize:12, fontFamily:'JetBrains Mono,monospace', resize:'none', minHeight:55, outline:'none', marginBottom:10 }}/>
        </>
      )}
      {inviteMode==='account' && (
        <>
          <label style={{ display:'block', fontSize:9, fontWeight:700, color:inRoom?'#a78bfa':'#7c3aed', marginBottom:5, textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace' }}>SEARCH STUDENT ACCOUNTS</label>
          <div style={{ position:'relative', marginBottom:8 }}>
            <span style={{ position:'absolute', left:10, top:'50%', transform:'translateY(-50%)', fontSize:12, color:inRoom?'rgba(255,255,255,.3)':'#9ca3af' }}>🔍</span>
            <input value={accountSearch}
              onChange={e=>{ setAccSearch(e.target.value); searchAccounts(e.target.value); }}
              onFocus={()=>{ if(!accountsLoaded) loadAllAccounts(); else setFoundAccts(allAccounts); }}
              placeholder="Type to search by name or email..."
              style={{ width:'100%', background:inRoom?'rgba(255,255,255,.06)':'#f8f8fc', border:`1px solid ${inRoom?'rgba(255,255,255,.1)':'#e5e7eb'}`, borderRadius:7, padding:'7px 11px 7px 30px', color:inRoom?'rgba(255,255,255,.8)':'#374151', fontSize:12, outline:'none' }}/>
            {searchingAcc&&<span style={{ position:'absolute', right:10, top:'50%', transform:'translateY(-50%)', fontSize:10, color:inRoom?'rgba(255,255,255,.3)':'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>Loading...</span>}
          </div>
          {foundAccounts.length>0&&(
            <div style={{ maxHeight:140, overflowY:'auto', background:inRoom?'rgba(255,255,255,.04)':'#f8f8fc', borderRadius:8, border:`1px solid ${inRoom?'rgba(255,255,255,.08)':'#e5e7eb'}`, marginBottom:8 }}>
              {foundAccounts.map(acc=>{
                const isSel=selectedAccounts.find(a=>a.user_id===acc.user_id);
                return (
                  <div key={acc.user_id} onClick={()=>toggleSelectAccount(acc)}
                    style={{ display:'flex', alignItems:'center', gap:10, padding:'9px 12px', cursor:'pointer', borderBottom:`1px solid ${inRoom?'rgba(255,255,255,.05)':'#f3f4f6'}`, background:isSel?inRoom?'rgba(109,40,217,.15)':'#ede9fe':'transparent' }}>
                    <div style={{ width:28, height:28, borderRadius:'50%', background:'#ede9fe', display:'flex', alignItems:'center', justifyContent:'center', fontSize:11, fontWeight:800, color:'#7c3aed', flexShrink:0 }}>{acc.name?.charAt(0).toUpperCase()}</div>
                    <div style={{ flex:1 }}>
                      <div style={{ fontSize:12, fontWeight:600, color:inRoom?'#fff':'#0f0f1a' }}>{acc.name}</div>
                      <div style={{ fontSize:10, color:inRoom?'rgba(255,255,255,.4)':'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>{acc.email}</div>
                    </div>
                    <div style={{ width:16, height:16, borderRadius:4, border:`2px solid ${isSel?'#7c3aed':'#d1d5db'}`, background:isSel?'#7c3aed':'transparent', display:'flex', alignItems:'center', justifyContent:'center' }}>
                      {isSel&&<span style={{ fontSize:9, color:'#fff', fontWeight:900 }}>✓</span>}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
          {selectedAccounts.length>0&&(
            <div style={{ display:'flex', flexWrap:'wrap', gap:5, marginBottom:8 }}>
              {selectedAccounts.map(a=>(
                <div key={a.user_id} style={{ display:'flex', alignItems:'center', gap:5, background:inRoom?'rgba(109,40,217,.2)':'#ede9fe', color:inRoom?'#c4b5fd':'#7c3aed', padding:'3px 9px', borderRadius:20, fontSize:11, fontWeight:600 }}>
                  {a.name}<span onClick={()=>toggleSelectAccount(a)} style={{ cursor:'pointer', opacity:.7 }}>✕</span>
                </div>
              ))}
            </div>
          )}
        </>
      )}
      <button onClick={sendInvites} disabled={inviting}
        style={{ width:'100%', padding:'9px', background:inviting?'#9ca3af':'#7c3aed', color:'#fff', border:'none', borderRadius:8, fontWeight:700, fontSize:13, cursor:'pointer', display:'flex', alignItems:'center', justifyContent:'center', gap:7 }}>
        {inviting?<><div className="spinner" style={{width:12,height:12,borderColor:'rgba(255,255,255,.3)',borderTopColor:'#fff'}}/>Sending...</>:`📨 Send ${inviteMode==='email'?'Email':'Account'} Invites`}
      </button>
      {inviteMsg&&<div style={{ marginTop:8, fontSize:11, color:inviteMsg.includes('✓')?'#16a34a':'#d97706', fontFamily:'JetBrains Mono,monospace' }}>{inviteMsg}</div>}
    </div>
  );

  // ══════════════════════════════════════════════════════════
  // SETUP PHASE
  // ══════════════════════════════════════════════════════════
  if (phase==='setup') {
    if (adminAway && awaySecondsLeft!==null) return (
      <div className="fade-up" style={{ maxWidth:560, margin:'0 auto' }}>
        <div style={{ background:'#fff', border:'2px solid #fde68a', borderRadius:16, padding:'28px', textAlign:'center', boxShadow:'0 4px 20px rgba(0,0,0,.08)' }}>
          <div style={{ fontSize:48, marginBottom:14 }}>⏳</div>
          <h2 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:22, color:'#0f0f1a', marginBottom:8 }}>Your Viva Session is Still Running</h2>
          <p style={{ fontSize:14, color:'#374151', lineHeight:1.65, marginBottom:10 }}>You left the viva room earlier. Return within the time limit to continue.</p>
          <div style={{ background:'#fef3c7', border:'1px solid #fde68a', borderRadius:10, padding:'12px 20px', marginBottom:20, display:'inline-block' }}>
            <div style={{ fontSize:11, color:'#92400e', fontFamily:'JetBrains Mono,monospace', marginBottom:4, letterSpacing:1 }}>AUTO-TERMINATION IN</div>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:36, color:'#d97706' }}>
              {Math.floor(awaySecondsLeft/60).toString().padStart(2,'0')}:{(awaySecondsLeft%60).toString().padStart(2,'0')}
            </div>
          </div>
          <div style={{ display:'flex', gap:12, justifyContent:'center' }}>
            <button onClick={handleAdminReturn}
              style={{ padding:'11px 28px', background:'linear-gradient(135deg,#16a34a,#15803d)', color:'#fff', border:'none', borderRadius:10, fontWeight:800, fontSize:14, cursor:'pointer', boxShadow:'0 4px 14px rgba(22,163,74,.3)' }}>
              ▶ Rejoin Viva Room
            </button>
            <button onClick={()=>{ localStorage.removeItem('viva_active_session'); setAdminAway(false); setAwayLeft(null); }}
              style={{ padding:'11px 20px', background:'#fff', color:'#dc2626', border:'1px solid #fecaca', borderRadius:10, fontWeight:700, fontSize:13, cursor:'pointer' }}>
              End Session
            </button>
          </div>
        </div>
      </div>
    );

    return (
      <div className="fade-up">
        <div style={{ display:'flex', alignItems:'center', gap:12, marginBottom:6 }}>
          <div style={{ width:40, height:40, borderRadius:10, background:'linear-gradient(135deg,#ede9fe,#ddd6fe)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:20 }}>🎓</div>
          <div>
            <h1 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:22, color:'#0f0f1a' }}>Viva Voce Room</h1>
            <p style={{ fontSize:12, color:'#7c3aed', fontFamily:'JetBrains Mono,monospace' }}>Live oral exam · Dual speech · Video recording · Auto-grading</p>
          </div>
        </div>
        <div style={{ display:'grid', gridTemplateColumns:'400px 1fr', gap:20, marginTop:20 }}>
          <div style={{ display:'flex', flexDirection:'column', gap:14 }}>
            <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:22, boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
              <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#0f0f1a', marginBottom:14 }}>⚙ Room Setup</div>
              {[{k:'title',l:'VIVA TITLE *',ph:'e.g. CS Final Viva — Batch 2024'},{k:'topic',l:'DEFAULT TOPIC',ph:'e.g. DBMS, OS, Data Structures...'}].map(f=>(
                <div key={f.k} style={{ marginBottom:10 }}>
                  <label style={{ display:'block', fontSize:9, fontWeight:700, color:'#7c3aed', marginBottom:4, textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace' }}>{f.l}</label>
                  <input className="form-input" value={form[f.k]} onChange={e=>setForm(p=>({...p,[f.k]:e.target.value}))} placeholder={f.ph}/>
                </div>
              ))}
              <button onClick={startRoom} disabled={!form.title.trim()}
                style={{ width:'100%', marginTop:6, padding:'10px', background:form.title.trim()?'linear-gradient(135deg,#16a34a,#15803d)':'#d1d5db', color:'#fff', border:'none', borderRadius:9, fontWeight:700, fontSize:13, cursor:form.title.trim()?'pointer':'not-allowed', display:'flex', alignItems:'center', justifyContent:'center', gap:7 }}>
                🎬 Start Viva Room
              </button>
            </div>
            <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:14, boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
              <div style={{ fontSize:11, fontWeight:700, color:'#374151', marginBottom:8 }}>ℹ You can invite students after entering the room</div>
              <div style={{ fontSize:11, color:'#6b7280' }}>Click "Start Viva Room" first, then use the ✉ Invite button inside the room.</div>
            </div>
          </div>
          <div>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#0f0f1a', marginBottom:12 }}>📋 Past Sessions</div>
            {pastSessions.length===0 ? (
              <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:40, textAlign:'center', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
                <div style={{ fontSize:36, marginBottom:10, opacity:.2 }}>🎓</div>
                <div style={{ fontSize:13, color:'#9ca3af' }}>No past sessions yet</div>
              </div>
            ) : (
              <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
                <table style={{ width:'100%', borderCollapse:'collapse' }}>
                  <thead><tr style={{ background:'#f8f8fc' }}>{['TITLE','TOPIC','DATE'].map(h=><th key={h} style={{ padding:'9px 14px', textAlign:'left', fontSize:9, fontWeight:700, color:'#9ca3af', textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace', borderBottom:'1px solid #f3f4f6' }}>{h}</th>)}</tr></thead>
                  <tbody>{pastSessions.slice(0,6).map((v,i)=>(
                    <tr key={i} style={{ borderBottom:'1px solid #f3f4f6' }} onMouseEnter={e=>e.currentTarget.style.background='#f8f8fc'} onMouseLeave={e=>e.currentTarget.style.background='transparent'}>
                      <td style={{ padding:'11px 14px', fontWeight:600, color:'#0f0f1a', fontSize:13 }}>{v.title}</td>
                      <td style={{ padding:'11px 14px', fontSize:12, color:'#7c3aed', fontFamily:'JetBrains Mono,monospace' }}>{v.topic||'—'}</td>
                      <td style={{ padding:'11px 14px', fontSize:11, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>{v.created_at?new Date(v.created_at).toLocaleDateString():'—'}</td>
                    </tr>
                  ))}</tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  // ══════════════════════════════════════════════════════════
  // LIVE ROOM
  // ══════════════════════════════════════════════════════════
  if (phase==='room') return (
    <div style={{ minHeight:'calc(100vh - 52px)', background:'#0d0d14', margin:'-28px -32px', padding:'14px 18px', display:'flex', flexDirection:'column', gap:12 }}>
      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', flexShrink:0 }}>
        <div style={{ display:'flex', alignItems:'center', gap:10 }}>
          <div style={{ display:'flex', alignItems:'center', gap:5, background:'rgba(220,38,38,.12)', border:'1px solid rgba(220,38,38,.3)', borderRadius:20, padding:'3px 10px' }}>
            <span style={{ width:6, height:6, borderRadius:'50%', background:'#dc2626', display:'inline-block', animation:'pulse 1s ease-in-out infinite' }}/>
            <span style={{ fontSize:9, fontWeight:800, color:'#fb7185', fontFamily:'JetBrains Mono,monospace', letterSpacing:1 }}>LIVE VIVA</span>
          </div>
          <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#fff' }}>{form.title}</span>
          {recording&&<span style={{ fontSize:9, color:'rgba(220,38,38,.7)', fontFamily:'JetBrains Mono,monospace', background:'rgba(220,38,38,.1)', padding:'2px 8px', borderRadius:10 }}>● REC</span>}
          {(savedVivaRef.current?.viva_id||savedViva?.viva_id)&&(
            <span onClick={()=>{navigator.clipboard.writeText(savedVivaRef.current?.viva_id||savedViva?.viva_id);store.addToast('Room ID copied!','success');}}
              style={{ fontSize:9, color:'rgba(167,139,250,.8)', fontFamily:'JetBrains Mono,monospace', background:'rgba(109,40,217,.15)', border:'1px solid rgba(109,40,217,.3)', padding:'2px 8px', borderRadius:6, cursor:'pointer' }}
              title="Click to copy Room ID">
              🔑 {(savedVivaRef.current?.viva_id||savedViva?.viva_id).slice(0,12)}... 📋
            </span>
          )}
          <span style={{ fontSize:10, color:'rgba(255,255,255,.3)', fontFamily:'JetBrains Mono,monospace' }}>{transcript.length} answered · {unusedQs.length} queued</span>
        </div>
        <div style={{ display:'flex', gap:8 }}>
          <button onClick={()=>setShowInvite(v=>!v)}
            style={{ padding:'6px 14px', background:showInvite?'rgba(109,40,217,.25)':'rgba(109,40,217,.12)', color:'#a78bfa', border:`1px solid ${showInvite?'rgba(109,40,217,.5)':'rgba(109,40,217,.25)'}`, borderRadius:8, fontWeight:700, fontSize:11, cursor:'pointer', fontFamily:'JetBrains Mono,monospace' }}>
            ✉ {showInvite?'Hide Invite':'Invite'}
          </button>
          <button onClick={()=>{ handleAdminLeave(); store.addToast('Viva paused. Return within 10 minutes.','warning'); setPhase('setup'); setAdminAway(true); setAwayLeft(AWAY_LIMIT_S); }}
            style={{ padding:'6px 14px', background:'rgba(245,158,11,.12)', color:'#fbbf24', border:'1px solid rgba(245,158,11,.25)', borderRadius:8, fontWeight:700, fontSize:11, cursor:'pointer', fontFamily:'JetBrains Mono,monospace' }}>
            ⏸ Leave (10 min)
          </button>
          <button onClick={endAndGrade}
            style={{ padding:'6px 16px', background:'rgba(220,38,38,.15)', color:'#fb7185', border:'1px solid rgba(220,38,38,.3)', borderRadius:8, fontWeight:700, fontSize:12, cursor:'pointer', fontFamily:'JetBrains Mono,monospace' }}>
            ⏹ End & Grade
          </button>
        </div>
      </div>

      {showInvite&&(
        <div style={{ background:'#1a1a2e', border:'1px solid rgba(109,40,217,.3)', borderRadius:12, padding:16 }}>
          <InvitePanel inRoom={true}/>
        </div>
      )}

      <div style={{ display:'grid', gridTemplateColumns:'240px 1fr 280px', gap:12, flex:1, minHeight:0 }}>
        {/* COL 1 */}
        <div style={{ display:'flex', flexDirection:'column', gap:10 }}>
          <div style={{ background:'#1a1a2e', borderRadius:11, overflow:'hidden', border:'1px solid rgba(255,255,255,.07)' }}>
            <div style={{ fontSize:9, fontWeight:700, color:'rgba(255,255,255,.35)', fontFamily:'JetBrains Mono,monospace', padding:'6px 10px', borderBottom:'1px solid rgba(255,255,255,.05)', display:'flex', alignItems:'center', gap:5 }}>
              <span style={{ width:5, height:5, borderRadius:'50%', background:camOn?'#22c55e':'#6b7280', display:'inline-block' }}/>ADMIN (EXAMINER)
            </div>
            <div style={{ position:'relative', aspectRatio:'4/3', background:'#000' }}>
              <video ref={adminVid} autoPlay muted playsInline style={{ width:'100%', height:'100%', objectFit:'cover', display:camOn?'block':'none' }}/>
              {!camOn&&<div style={{ position:'absolute', inset:0, display:'flex', alignItems:'center', justifyContent:'center' }}><div style={{ fontSize:28, opacity:.25 }}>👤</div></div>}
            </div>
            <div style={{ display:'flex', gap:4, padding:5 }}>
              <button onClick={toggleCam} style={{ flex:1, padding:'4px', borderRadius:5, border:'none', background:camOn?'rgba(34,197,94,.12)':'rgba(255,255,255,.04)', color:camOn?'#4ade80':'rgba(255,255,255,.3)', cursor:'pointer', fontSize:9, fontWeight:700 }}>{camOn?'📹 ON':'📷 OFF'}</button>
              <button onClick={toggleExaminer} style={{ flex:1, padding:'4px', borderRadius:5, border:'none', background:examinerRec?'rgba(234,179,8,.12)':'rgba(255,255,255,.04)', color:examinerRec?'#fbbf24':'rgba(255,255,255,.3)', cursor:'pointer', fontSize:9, fontWeight:700 }}>{examinerRec?'🎙 REC':'🎙 MIC'}</button>
            </div>
          </div>
          <div style={{ background:'#1a1a2e', borderRadius:11, overflow:'hidden', border:'1px solid rgba(255,255,255,.07)' }}>
            <div style={{ fontSize:9, fontWeight:700, color:'rgba(255,255,255,.35)', fontFamily:'JetBrains Mono,monospace', padding:'6px 10px', borderBottom:'1px solid rgba(255,255,255,.05)' }}>STUDENT SCREEN</div>
            <div style={{ aspectRatio:'4/3', background:'#000', display:'flex', alignItems:'center', justifyContent:'center', flexDirection:'column', gap:5 }}>
              <div style={{ fontSize:24, opacity:.15 }}>👥</div>
              <div style={{ fontSize:9, color:'rgba(255,255,255,.15)', fontFamily:'JetBrains Mono,monospace', textAlign:'center' }}>Student joins via Viva tab</div>
            </div>
          </div>
          <div style={{ background:'#1a1a2e', borderRadius:11, border:'1px solid rgba(109,40,217,.22)', padding:12, flex:1 }}>
            <div style={{ fontSize:9, fontWeight:700, color:'#a78bfa', fontFamily:'JetBrains Mono,monospace', marginBottom:9, letterSpacing:1 }}>⚡ QUESTION GENERATOR</div>
            <input value={genTopic} onChange={e=>setGenTopic(e.target.value)} placeholder="Topic (e.g. SQL, Trees, OS)" onKeyDown={e=>e.key==='Enter'&&generateQuestions()}
              style={{ width:'100%', background:'rgba(255,255,255,.05)', border:'1px solid rgba(255,255,255,.08)', borderRadius:6, padding:'7px 9px', color:'#fff', fontSize:11, fontFamily:'JetBrains Mono,monospace', outline:'none', marginBottom:7 }}/>
            <div style={{ display:'flex', gap:5, marginBottom:8 }}>
              {[3,5,7].map(n=>(
                <button key={n} onClick={()=>setGenCount(n)}
                  style={{ flex:1, padding:'4px', borderRadius:5, border:`1px solid ${genCount===n?'rgba(167,139,250,.4)':'rgba(255,255,255,.07)'}`, background:genCount===n?'rgba(167,139,250,.12)':'transparent', color:genCount===n?'#a78bfa':'rgba(255,255,255,.3)', fontSize:10, fontWeight:700, cursor:'pointer', fontFamily:'JetBrains Mono,monospace' }}>{n}Q</button>
              ))}
            </div>
            <button onClick={generateQuestions} disabled={generating||!genTopic.trim()}
              style={{ width:'100%', padding:'8px', background:generating||!genTopic.trim()?'rgba(255,255,255,.05)':'linear-gradient(135deg,#6d28d9,#7c3aed)', color:generating||!genTopic.trim()?'rgba(255,255,255,.2)':'#fff', border:'none', borderRadius:7, fontWeight:700, fontSize:11, cursor:generating||!genTopic.trim()?'not-allowed':'pointer', display:'flex', alignItems:'center', justifyContent:'center', gap:6 }}>
              {generating?<><div className="spinner" style={{width:11,height:11,borderColor:'rgba(255,255,255,.2)',borderTopColor:'#fff'}}/>Generating...</>:'⚡ Generate + Answers'}
            </button>
          </div>
        </div>

        {/* COL 2 */}
        <div style={{ display:'flex', flexDirection:'column', gap:10 }}>
          <div style={{ background:'#1a1a2e', borderRadius:11, padding:16, border:`1px solid ${currentQ?'rgba(109,40,217,.35)':'rgba(255,255,255,.05)'}`, flexShrink:0 }}>
            <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:10 }}>
              <span style={{ fontSize:9, fontWeight:700, color:'rgba(255,255,255,.35)', fontFamily:'JetBrains Mono,monospace', letterSpacing:1 }}>CURRENT QUESTION</span>
              {currentQ&&<span style={{ fontSize:9, background:'rgba(167,139,250,.12)', color:'#a78bfa', padding:'2px 7px', borderRadius:20, fontFamily:'JetBrains Mono,monospace' }}>{questions.indexOf(currentQ)+1}/{questions.length}</span>}
            </div>
            {currentQ ? (
              <>
                <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:17, color:'#fff', lineHeight:1.5, marginBottom:10 }}>{currentQ.text}</div>
                <div style={{ background:'rgba(34,197,94,.07)', border:'1px solid rgba(34,197,94,.18)', borderRadius:8, padding:'9px 12px' }}>
                  <div style={{ fontSize:8, fontWeight:700, color:'#4ade80', fontFamily:'JetBrains Mono,monospace', marginBottom:5, letterSpacing:1 }}>✅ MODEL ANSWER (EXAMINER VIEW)</div>
                  <div style={{ fontSize:12, color:'rgba(74,222,128,.85)', lineHeight:1.6 }}>{currentQ.modelAnswer}</div>
                </div>
              </>
            ) : (
              <div style={{ color:'rgba(255,255,255,.2)', fontSize:13, fontStyle:'italic', fontFamily:'JetBrains Mono,monospace' }}>{questions.length===0?'Generate questions →':'Click a question from the right →'}</div>
            )}
          </div>
          <div style={{ background:'#1a1a2e', borderRadius:11, padding:14, border:'1px solid rgba(255,255,255,.05)', flex:1, display:'flex', flexDirection:'column' }}>
            <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:10 }}>
              <div style={{ display:'flex', alignItems:'center', gap:6 }}>
                {studentRec&&<span style={{ width:6, height:6, borderRadius:'50%', background:'#dc2626', display:'inline-block', animation:'pulse 1s ease-in-out infinite' }}/>}
                <span style={{ fontSize:9, fontWeight:700, color:'rgba(255,255,255,.35)', fontFamily:'JetBrains Mono,monospace', letterSpacing:1 }}>{studentRec?'🎙 RECORDING...':'STUDENT ANSWER'}</span>
              </div>
              <button onClick={toggleStudent} disabled={!currentQ}
                style={{ padding:'5px 13px', borderRadius:7, border:'none', background:studentRec?'rgba(220,38,38,.15)':'rgba(109,40,217,.18)', color:studentRec?'#fb7185':'#a78bfa', fontWeight:700, fontSize:11, cursor:currentQ?'pointer':'not-allowed', fontFamily:'JetBrains Mono,monospace', opacity:currentQ?1:.4 }}>
                {studentRec?'⏸ Stop':'🎙 Record Student'}
              </button>
            </div>
            <div style={{ flex:1, minHeight:60, marginBottom:8, fontSize:14, color:studentLive?'rgba(255,255,255,.85)':'rgba(255,255,255,.2)', lineHeight:1.75, fontStyle:studentLive?'normal':'italic' }}>
              {studentLive||'Student speech appears here...'}{studentInt&&<span style={{ color:'rgba(255,255,255,.4)', fontStyle:'italic' }}> {studentInt}</span>}
            </div>
            <textarea value={examNotes} onChange={e=>setExamNotes(e.target.value)} placeholder="Examiner notes / corrections..."
              style={{ width:'100%', background:'rgba(255,255,255,.04)', border:'1px solid rgba(255,255,255,.07)', borderRadius:6, padding:'7px 10px', color:'rgba(255,255,255,.6)', fontSize:11, fontFamily:'JetBrains Mono,monospace', resize:'none', minHeight:45, outline:'none', marginBottom:10 }}/>
            {liveVerdict&&(
              <div style={{ marginBottom:10, background:liveVerdict.correct?'rgba(34,197,94,.08)':liveVerdict.verdict==='Partially Correct'?'rgba(245,158,11,.08)':'rgba(220,38,38,.08)', border:`1px solid ${liveVerdict.correct?'rgba(34,197,94,.3)':liveVerdict.verdict==='Partially Correct'?'rgba(245,158,11,.3)':'rgba(220,38,38,.3)'}`, borderRadius:8, padding:'9px 12px' }}>
                <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:5 }}>
                  <span style={{ fontSize:14 }}>{liveVerdict.correct?'✅':liveVerdict.verdict==='Partially Correct'?'⚠️':'❌'}</span>
                  <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:12, color:liveVerdict.correct?'#4ade80':liveVerdict.verdict==='Partially Correct'?'#fbbf24':'#fb7185' }}>{liveVerdict.verdict}</span>
                  <span style={{ fontSize:9, color:'rgba(255,255,255,.3)', fontFamily:'JetBrains Mono,monospace', marginLeft:'auto' }}>{liveVerdict.score_pct}%</span>
                </div>
                <div style={{ fontSize:11, color:'rgba(255,255,255,.6)', lineHeight:1.5 }}>{liveVerdict.feedback}</div>
                {liveVerdict.missing&&liveVerdict.missing!=='None'&&<div style={{ fontSize:10, color:'rgba(251,191,36,.7)', fontFamily:'JetBrains Mono,monospace', marginTop:4 }}>⚠ Missing: {liveVerdict.missing}</div>}
              </div>
            )}
          </div>
          <div style={{ display:'flex', gap:8, flexShrink:0 }}>
            <button onClick={()=>{setStudentLive('');setStudentInt('');setExamNotes('');setLiveVerdict(null);speech.stopChannel('student');setStudentRec(false);}}
              style={{ flex:1, padding:'9px', background:'rgba(255,255,255,.05)', color:'rgba(255,255,255,.45)', border:'1px solid rgba(255,255,255,.07)', borderRadius:9, fontWeight:600, fontSize:12, cursor:'pointer' }}>🔄</button>
            <button onClick={checkAnswer} disabled={verdicting||!currentQ||(!studentLive&&!examNotes)}
              style={{ flex:1.5, padding:'9px', background:verdicting||!currentQ||(!studentLive&&!examNotes)?'rgba(255,255,255,.05)':'rgba(245,158,11,.15)', color:verdicting||!currentQ||(!studentLive&&!examNotes)?'rgba(255,255,255,.2)':'#fbbf24', border:`1px solid ${verdicting||!currentQ||(!studentLive&&!examNotes)?'rgba(255,255,255,.07)':'rgba(245,158,11,.3)'}`, borderRadius:9, fontWeight:700, fontSize:12, cursor:currentQ&&(studentLive||examNotes)?'pointer':'not-allowed', display:'flex', alignItems:'center', justifyContent:'center', gap:5 }}>
              {verdicting?<><div className="spinner" style={{width:11,height:11}}/>...</>:'⚡ Check'}
            </button>
            <button onClick={saveAnswer} disabled={!currentQ||(!studentLive&&!examNotes)}
              style={{ flex:2, padding:'9px', background:currentQ&&(studentLive||examNotes)?'linear-gradient(135deg,#16a34a,#15803d)':'rgba(255,255,255,.05)', color:currentQ&&(studentLive||examNotes)?'#fff':'rgba(255,255,255,.2)', border:'none', borderRadius:9, fontWeight:800, fontSize:12, cursor:currentQ&&(studentLive||examNotes)?'pointer':'not-allowed' }}>
              ✓ Save & Next →
            </button>
          </div>
        </div>

        {/* COL 3 */}
        <div style={{ display:'flex', flexDirection:'column', gap:10 }}>
          <div style={{ background:'#1a1a2e', borderRadius:11, overflow:'hidden', border:'1px solid rgba(255,255,255,.06)', flex:1 }}>
            <div style={{ padding:'8px 12px', borderBottom:'1px solid rgba(255,255,255,.05)', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
              <span style={{ fontSize:9, fontWeight:700, color:'rgba(255,255,255,.35)', fontFamily:'JetBrains Mono,monospace', letterSpacing:1 }}>QUESTIONS ({questions.length})</span>
              <span style={{ fontSize:9, color:'rgba(255,255,255,.2)', fontFamily:'JetBrains Mono,monospace' }}>{unusedQs.length} left</span>
            </div>
            <div style={{ overflowY:'auto', maxHeight:320, padding:7 }}>
              {questions.length===0
                ? <div style={{ padding:16, textAlign:'center', fontSize:10, color:'rgba(255,255,255,.15)', fontFamily:'JetBrains Mono,monospace' }}>Generate questions on the left</div>
                : questions.map((q,i)=>(
                  <div key={q.id} onClick={()=>!q.used&&setCurrentQ(q)}
                    style={{ padding:'8px 10px', borderRadius:7, marginBottom:4, cursor:q.used?'default':'pointer', background:currentQ?.id===q.id?'rgba(109,40,217,.18)':q.used?'rgba(34,197,94,.05)':'rgba(255,255,255,.02)', border:`1px solid ${currentQ?.id===q.id?'rgba(109,40,217,.35)':q.used?'rgba(34,197,94,.12)':'rgba(255,255,255,.04)'}`, opacity:q.used?.6:1 }}>
                    <div style={{ fontSize:8, fontWeight:800, fontFamily:'JetBrains Mono,monospace', color:q.used?'#4ade80':currentQ?.id===q.id?'#a78bfa':'rgba(255,255,255,.3)', marginBottom:2 }}>Q{i+1} {q.used?'✓':currentQ?.id===q.id?'▶':''} <span style={{ fontWeight:400, opacity:.5 }}>{q.topic}</span></div>
                    <div style={{ fontSize:10, color:q.used?'rgba(74,222,128,.5)':currentQ?.id===q.id?'#fff':'rgba(255,255,255,.55)', lineHeight:1.4 }}>{q.text.length>65?q.text.slice(0,65)+'…':q.text}</div>
                  </div>
                ))
              }
            </div>
          </div>
          <div style={{ background:'#1a1a2e', borderRadius:11, overflow:'hidden', border:'1px solid rgba(255,255,255,.06)', flexShrink:0 }}>
            <div style={{ padding:'8px 12px', borderBottom:'1px solid rgba(255,255,255,.05)' }}>
              <span style={{ fontSize:9, fontWeight:700, color:'rgba(255,255,255,.35)', fontFamily:'JetBrains Mono,monospace', letterSpacing:1 }}>TRANSCRIPT ({transcript.length})</span>
            </div>
            <div style={{ maxHeight:200, overflowY:'auto', padding:7 }}>
              {transcript.length===0
                ? <div style={{ padding:14, textAlign:'center', fontSize:10, color:'rgba(255,255,255,.15)', fontFamily:'JetBrains Mono,monospace' }}>Saved answers appear here</div>
                : transcript.map((t,i)=>{
                  const vc=t.verdict==='Correct'?'#4ade80':t.verdict==='Partially Correct'?'#fbbf24':'#fb7185';
                  return (
                    <div key={i} style={{ padding:'7px 9px', borderRadius:6, marginBottom:4, background:'rgba(255,255,255,.02)', border:`1px solid ${t.verdict==='Correct'?'rgba(34,197,94,.12)':t.verdict==='Partially Correct'?'rgba(245,158,11,.12)':'rgba(220,38,38,.12)'}` }}>
                      <div style={{ display:'flex', justifyContent:'space-between', marginBottom:2 }}>
                        <span style={{ fontSize:8, color:'#a78bfa', fontFamily:'JetBrains Mono,monospace' }}>Q{i+1}</span>
                        <span style={{ fontSize:8, fontWeight:800, color:vc, fontFamily:'JetBrains Mono,monospace' }}>{t.verdict||'?'}</span>
                      </div>
                      <div style={{ fontSize:10, color:'rgba(255,255,255,.5)', lineHeight:1.4 }}>{t.studentAnswer.slice(0,70)}{t.studentAnswer.length>70?'…':''}</div>
                    </div>
                  );
                })
              }
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  // ══════════════════════════════════════════════════════════
  // RESULTS PHASE
  // ══════════════════════════════════════════════════════════
  return (
    <div className="fade-up">
      <div style={{ display:'flex', alignItems:'center', gap:12, marginBottom:22 }}>
        <button onClick={resetAll} style={{ padding:'6px 14px', background:'#fff', border:'1px solid #e5e7eb', borderRadius:8, fontSize:12, fontWeight:600, color:'#374151', cursor:'pointer' }}>← New Viva</button>
        <h1 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:22, color:'#0f0f1a' }}>Viva Results</h1>
        <span style={{ fontSize:11, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>{form.title}</span>
        {videoBlob&&<button onClick={()=>{ const url=URL.createObjectURL(videoBlob); const a=document.createElement('a'); a.href=url; a.download=`viva-${Date.now()}.webm`; a.click(); URL.revokeObjectURL(url); }} style={{ marginLeft:'auto', padding:'7px 16px', background:'#ede9fe', border:'1px solid #ddd6fe', borderRadius:8, fontSize:12, fontWeight:700, color:'#7c3aed', cursor:'pointer' }}>📹 Download Recording</button>}
      </div>
      {grading ? (
        <div style={{ textAlign:'center', padding:'80px 0' }}>
          <div style={{ width:56, height:56, borderRadius:'50%', border:'4px solid #e8e8f0', borderTop:'4px solid #7c3aed', animation:'spin .8s linear infinite', margin:'0 auto 16px' }}/>
          <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:18, color:'#0f0f1a', marginBottom:6 }}>Grading {transcript.length} answers...</div>
          <div style={{ fontSize:13, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>Score normalised to 100</div>
        </div>
      ) : result ? (
        <>
          <div style={{ background:gcBg(result.grade), border:`1px solid ${gc(result.grade)}33`, borderRadius:16, padding:'22px 26px', marginBottom:18, display:'flex', alignItems:'center', gap:22 }}>
            <div style={{ width:78, height:78, borderRadius:'50%', background:gc(result.grade), display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', flexShrink:0, boxShadow:`0 0 28px ${gc(result.grade)}44` }}>
              <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:26, color:'#fff', lineHeight:1 }}>{result.grade}</div>
              <div style={{ fontSize:8, color:'rgba(255,255,255,.75)', fontFamily:'JetBrains Mono,monospace' }}>GRADE</div>
            </div>
            <div style={{ flex:1 }}>
              <div style={{ display:'flex', alignItems:'baseline', gap:10, marginBottom:4 }}>
                <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:42, color:gc(result.grade), lineHeight:1 }}>{result.total_score}</span>
                <span style={{ fontSize:18, color:'#9ca3af', fontWeight:400 }}>/100</span>
                <span style={{ padding:'3px 12px', borderRadius:20, background:`${gc(result.grade)}18`, color:gc(result.grade), fontSize:12, fontWeight:700 }}>{result.correct_count||0} correct · {result.incorrect_count||0} incorrect</span>
              </div>
              <div style={{ fontSize:14, color:'#374151', marginBottom:10, lineHeight:1.65 }}>{result.overall_feedback}</div>
              <div style={{ height:8, background:'#e8e8f0', borderRadius:4, overflow:'hidden', maxWidth:440 }}>
                <div style={{ height:'100%', width:`${result.total_score}%`, background:`linear-gradient(90deg,${gc(result.grade)}88,${gc(result.grade)})`, borderRadius:4 }}/>
              </div>
            </div>
            <div style={{ display:'flex', flexDirection:'column', gap:7, flexShrink:0 }}>
              {(result.strengths||[]).slice(0,2).map((s,i)=>(
                <div key={i} style={{ background:'#dcfce7', border:'1px solid #bbf7d0', borderRadius:7, padding:'5px 11px', fontSize:11, color:'#16a34a', fontWeight:600 }}>✓ {s}</div>
              ))}
            </div>
          </div>
          <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)', marginBottom:16 }}>
            <div style={{ padding:'14px 20px', borderBottom:'1px solid #f3f4f6', fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#0f0f1a' }}>📋 Question Breakdown</div>
            {(result.answers||[]).map((a,i)=>{
              const color=a.correct?'#16a34a':a.verdict==='Partially Correct'?'#d97706':'#dc2626';
              return (
                <div key={i} style={{ padding:'14px 20px', borderBottom:'1px solid #f3f4f6', borderLeft:`4px solid ${color}` }}>
                  <div style={{ display:'flex', alignItems:'flex-start', gap:12 }}>
                    <div style={{ width:28, height:28, borderRadius:7, background:`${color}15`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:12, fontWeight:800, color, flexShrink:0 }}>{a.correct?'✓':a.verdict==='Partially Correct'?'~':'✗'}</div>
                    <div style={{ flex:1 }}>
                      <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:13, color:'#0f0f1a', marginBottom:5 }}>Q{i+1}: {a.question}</div>
                      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:8, marginBottom:7 }}>
                        <div style={{ background:'#f0fdf4', border:'1px solid #bbf7d0', borderRadius:7, padding:'6px 10px' }}>
                          <div style={{ fontSize:8, fontWeight:700, color:'#16a34a', fontFamily:'JetBrains Mono,monospace', marginBottom:3, letterSpacing:1 }}>MODEL</div>
                          <div style={{ fontSize:11, color:'#166534', lineHeight:1.5 }}>{a.model_answer_summary}</div>
                        </div>
                        <div style={{ background:'#f8f8fc', border:'1px solid #e8e8f0', borderRadius:7, padding:'6px 10px' }}>
                          <div style={{ fontSize:8, fontWeight:700, color:'#6b7280', fontFamily:'JetBrains Mono,monospace', marginBottom:3, letterSpacing:1 }}>STUDENT</div>
                          <div style={{ fontSize:11, color:'#374151', fontStyle:'italic' }}>"{a.student_said}"</div>
                        </div>
                      </div>
                      <div style={{ background:'#f8f8fc', border:'1px solid #e8e8f0', borderRadius:7, padding:'6px 10px', marginBottom:7, fontSize:12, color:'#374151', lineHeight:1.5 }}>💡 {a.feedback}</div>
                      <div style={{ display:'flex', alignItems:'center', gap:10 }}>
                        <span style={{ padding:'2px 10px', borderRadius:20, background:`${color}15`, color, fontSize:10, fontWeight:800 }}>{a.verdict}</span>
                        <div style={{ flex:1, maxWidth:160, height:5, background:'#f3f4f6', borderRadius:3, overflow:'hidden' }}>
                          <div style={{ height:'100%', width:`${Math.round(a.score/a.max_score*100)}%`, background:`linear-gradient(90deg,${color}88,${color})`, borderRadius:3 }}/>
                        </div>
                        <span style={{ fontFamily:'JetBrains Mono,monospace', fontWeight:800, fontSize:12, color }}>{a.score}/{a.max_score}</span>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
          <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
            <div style={{ padding:'14px 20px', borderBottom:'1px solid #f3f4f6', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
              <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#0f0f1a' }}>📄 Full Transcript</span>
              <button onClick={()=>navigator.clipboard.writeText(fullTxt).then(()=>store.addToast('Copied!','success'))} style={{ padding:'5px 14px', background:'#f3f4f6', border:'1px solid #e5e7eb', borderRadius:7, fontSize:12, fontWeight:600, color:'#374151', cursor:'pointer' }}>📋 Copy</button>
            </div>
            <pre style={{ padding:20, fontFamily:'JetBrains Mono,monospace', fontSize:12, color:'#374151', lineHeight:1.85, whiteSpace:'pre-wrap', wordBreak:'break-word', maxHeight:320, overflowY:'auto', background:'#f8f8fc' }}>{fullTxt}</pre>
          </div>
        </>
      ) : <div className="empty-state"><div className="empty-icon">⚠</div><div className="empty-title">Grading failed</div></div>}
    </div>
  );
}
